"      // 1. Sync empty active state to the server database first so the backend drops the active state for this session
      try {
        if (posService && posService.saveActiveState) {
          await posService.saveActiveState({
            tableBills: {},
            tableStatuses: {},
            tableBillNumbers: {},
            tableActiveTimestamps: {},
            tables: []
          });
        }
      } catch (err) {
        console.error("Failed to clear server active state:", err);
      }

      // 1b. Wipe all sales, KOT, customer, and loyalty data from the backend database
      try {
        if (posService && posService.clearSalesData) {
          await posService.clearSalesData();
        }
      } catch (err) {
        console.error("Failed to wipe database sales data:", err);
      }"

